package io.aegis.validation;

import io.aegis.planning.DataReconciliationPlanner;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.SQLFeatureNotSupportedException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/** Executes only scalar COUNT SELECT checks generated by DataReconciliationPlanner. */
public final class DataReconciliationExecutor {
    private static final int QUERY_TIMEOUT_SECONDS = 60;
    private static final int MAX_CHECKS = 10_000;
    private static final Pattern SELECT_PREFIX = Pattern.compile("(?is)^\\s*SELECT\\b.*$");
    private static final Set<String> ZERO_EXPECTED = Set.of(
            "DUPLICATE_PRIMARY_KEYS", "NULL_PRIMARY_KEYS", "REQUIRED_COLUMN_NULLS", "ORPHAN_FOREIGN_KEYS");

    public ExecutionReport execute(DataReconciliationPlanner.Plan plan, Connection source,
                                   Connection target, boolean approveDiagnostics) {
        if (plan == null) throw new IllegalArgumentException("reconciliation plan is required");
        List<String> diagnostics = new ArrayList<>();
        List<CheckResult> results = new ArrayList<>();
        if (plan.checks().isEmpty())
            return new ExecutionReport(false, false, 0, results,
                    List.of("NO_RECONCILIATION_CHECKS: The plan contains no executable validation checks."));
        if (plan.checks().size() > MAX_CHECKS)
            return new ExecutionReport(false, false, 0, results,
                    List.of("CHECK_LIMIT_EXCEEDED: Plan exceeds " + MAX_CHECKS + " checks."));
        if (!plan.diagnostics().isEmpty() && !approveDiagnostics)
            return new ExecutionReport(false, false, 0, results,
                    List.of("DIAGNOSTICS_REQUIRE_APPROVAL: Review and explicitly approve all plan diagnostics before executing checks."));
        if (source == null || target == null)
            throw new IllegalArgumentException("source and target connections are required");

        boolean sourceWasReadOnly;
        boolean targetWasReadOnly;
        try {
            sourceWasReadOnly = source.isReadOnly();
            targetWasReadOnly = target.isReadOnly();
        } catch (SQLException failure) {
            return new ExecutionReport(false, false, 0, results,
                    List.of("CONNECTION_STATE_READ_FAILED: " + failure.getMessage()));
        }

        boolean sourceReadOnlyChanged = false;
        boolean targetReadOnlyChanged = false;
        int executed = 0;
        boolean executionStarted = false;
        boolean passed = true;
        try {
            sourceReadOnlyChanged = requestReadOnly(source, sourceWasReadOnly, "source", diagnostics);
            targetReadOnlyChanged = requestReadOnly(target, targetWasReadOnly, "target", diagnostics);
            if (!plan.diagnostics().isEmpty())
                diagnostics.add("DIAGNOSTICS_APPROVED: Caller explicitly approved the plan diagnostics.");

            for (DataReconciliationPlanner.Check check : plan.checks()) {
                Long sourceValue = null;
                Long targetValue = null;
                try {
                    validateCheckType(check.type());
                    validateSelect(check.sourceSql());
                    validateSelect(check.targetSql());
                    sourceValue = executeScalar(source, check.sourceSql());
                    executionStarted = true;
                    targetValue = executeScalar(target, check.targetSql());
                    boolean checkPassed = evaluate(check.type(), sourceValue, targetValue);
                    executed++;
                    if (!checkPassed) passed = false;
                    results.add(new CheckResult(check.id(), check.type(), sourceValue, targetValue,
                            checkPassed, check.expectedResult(), null));
                } catch (SQLException | IllegalArgumentException failure) {
                    passed = false;
                    results.add(new CheckResult(check.id(), check.type(), sourceValue, targetValue, false,
                            check.expectedResult(), failure.getMessage()));
                }
            }
        } catch (SQLException failure) {
            diagnostics.add("CONNECTION_PREPARATION_FAILED: " + failure.getMessage());
            passed = false;
        } finally {
            if (sourceReadOnlyChanged) restoreReadOnly(source, sourceWasReadOnly, "source", diagnostics);
            if (targetReadOnlyChanged) restoreReadOnly(target, targetWasReadOnly, "target", diagnostics);
        }
        boolean restoreFailed = diagnostics.stream().anyMatch(d -> d.startsWith("READ_ONLY_MODE_RESTORE_FAILED"));
        return new ExecutionReport(executionStarted,
                passed && !restoreFailed && results.size() == plan.checks().size()
                        && results.stream().allMatch(CheckResult::passed),
                executed, results, diagnostics);
    }

    private static boolean requestReadOnly(Connection connection, boolean wasReadOnly, String side,
                                            List<String> diagnostics) throws SQLException {
        if (wasReadOnly) return false;
        try {
            connection.setReadOnly(true);
        } catch (SQLFeatureNotSupportedException unsupported) {
            diagnostics.add("READ_ONLY_HINT_UNSUPPORTED: " + side
                    + " JDBC driver does not support setReadOnly; database grants must enforce read-only access.");
            return false;
        }
        if (!connection.isReadOnly()) {
            diagnostics.add("READ_ONLY_HINT_NOT_CONFIRMED: " + side
                    + " JDBC driver did not confirm read-only mode; only generated COUNT SELECT statements are executed.");
            return false;
        }
        return true;
    }

    private static void restoreReadOnly(Connection connection, boolean wasReadOnly, String side,
                                        List<String> diagnostics) {
        try {
            connection.setReadOnly(wasReadOnly);
        } catch (SQLException failure) {
            diagnostics.add("READ_ONLY_MODE_RESTORE_FAILED: " + side + " connection: " + failure.getMessage());
        }
    }

    private static long executeScalar(Connection connection, String sql) throws SQLException {
        try (Statement statement = connection.createStatement()) {
            statement.setQueryTimeout(QUERY_TIMEOUT_SECONDS);
            statement.setMaxRows(1);
            try (ResultSet result = statement.executeQuery(sql)) {
                if (!result.next()) throw new SQLException("Validation query returned no result row");
                long value = result.getLong(1);
                if (result.wasNull()) throw new SQLException("Validation query returned a null scalar");
                return value;
            }
        }
    }

    private static void validateCheckType(String type) {
        if (!"ROW_COUNT".equals(type) && !ZERO_EXPECTED.contains(type))
            throw new IllegalArgumentException("Unsupported reconciliation check type: " + type);
    }

    private static void validateSelect(String sql) {
        if (sql == null || !SELECT_PREFIX.matcher(sql).matches())
            throw new IllegalArgumentException("Only a single SELECT statement is permitted");
        String upper = sql.toUpperCase(Locale.ROOT);
        if (!upper.stripLeading().startsWith("SELECT COUNT(*)")
                || sql.contains(";") || sql.contains("--") || sql.contains("/*") || sql.contains("*/")
                || sql.contains("#") || upper.contains("INSERT ") || upper.contains("UPDATE ")
                || upper.contains("DELETE ") || upper.contains("MERGE ") || upper.contains("CREATE ")
                || upper.contains("ALTER ") || upper.contains("DROP ") || upper.contains("TRUNCATE ")
                || upper.contains("EXEC ") || upper.contains("CALL ") || upper.contains("GRANT ")
                || upper.contains("REVOKE ") || upper.contains("UNION ") || upper.contains("INTERSECT ")
                || upper.contains("EXCEPT ") || upper.contains("FOR UPDATE") || upper.contains("NEXTVAL")
                || upper.contains("PG_SLEEP") || upper.contains("DBMS_") || upper.contains("WAITFOR ")
                || upper.contains("OPENROWSET") || upper.contains("XP_CMDSHELL") || upper.contains("UTL_")
                || upper.contains("LOAD_FILE") || upper.contains("OUTFILE") || upper.contains("INFILE"))
            throw new IllegalArgumentException("Validation SQL contains a forbidden token or is not a generated COUNT query");
    }

    private static boolean evaluate(String type, long source, long target) {
        if ("ROW_COUNT".equals(type)) return source == target;
        return source == 0 && target == 0;
    }

    public record CheckResult(String checkId, String type, Long sourceValue, Long targetValue,
                              boolean passed, String expectedResult, String error) {}
    public record ExecutionReport(boolean executed, boolean passed, int checksExecuted,
                                  List<CheckResult> results, List<String> diagnostics) {
        public ExecutionReport {
            results = List.copyOf(results);
            diagnostics = List.copyOf(diagnostics);
        }
    }
}
